<template><div class="app-container"><el-form inline @submit.prevent="search"><el-form-item label="模块"><el-select v-model="q.kind" clearable style="width:140px"><el-option v-for="(v,k) in kindLabels" :key="k" :value="k" :label="v"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="q.status" clearable style="width:160px"><el-option v-for="(v,k) in reviewLabels" :key="k" :value="k" :label="v"/></el-select></el-form-item><el-form-item><el-checkbox v-model="q.mine">我提交的</el-checkbox></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button></el-form-item></el-form><el-alert title="审核的是固定快照。提交人和实际保存人不能自审；审核通过后仍需有发布权限的人单独发布。" :closable="false"/><el-table :data="rows" v-loading="loading"><el-table-column prop="reviewId" label="申请" width="80"/><el-table-column label="模块"><template #default="s">{{kindLabels[s.row.kind]}} #{{s.row.objectId}}</template></el-table-column><el-table-column prop="contentVersion" label="工作版本" width="90"/><el-table-column label="状态"><template #default="s">{{reviewLabels[s.row.status]}}</template></el-table-column><el-table-column prop="createBy" label="提交人"/><el-table-column prop="createTime" label="时间" width="170"/><el-table-column label="操作"><template #default="s"><el-button link type="primary" @click="detail.open(s.row.reviewId)">快照与审核</el-button></template></el-table-column></el-table><pagination v-if="total" :total="total" v-model:page="q.pageNum" v-model:limit="q.pageSize" @pagination="load"/><ReviewDetail ref="detail" @changed="load"/></div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated,watch}from'vue';import{useRoute}from'vue-router';import{workflow,kindLabels,reviewLabels}from'@/api/cms/workflow';import ReviewDetail from '../components/ReviewDetail.vue'
const route=useRoute(),detail=ref(),rows=ref([]),total=ref(0),loading=ref(false),q=reactive({kind:'',status:'',mine:false,pageNum:1,pageSize:10});let epoch=0
async function load(){const n=++epoch;loading.value=true;try{const r=await workflow('review/list','get',undefined,{...q});if(n===epoch){rows.value=r.rows;total.value=r.total}}finally{if(n===epoch)loading.value=false}}function search(){q.pageNum=1;load()}
function routeOpen(){if(route.path!=='/cms/review')return;const id=Number(route.query.reviewId);if(Number.isSafeInteger(id)&&id>0)detail.value?.open(id)}watch(()=>route.query.reviewId,routeOpen);onMounted(()=>{load();routeOpen()});function close(){++epoch;detail.value?.close()}onBeforeUnmount(close);let resumed=false;onDeactivated(()=>{resumed=true;close()});onActivated(()=>{if(resumed){resumed=false;load();routeOpen()}})
</script>
